  //     Promise -- NOT the asynchronous continuation of `customFunction`
  //     (e.g. an unresolved `fetch()` or an intentionally-never-resolving Promise).
  const result: unknown = await runInNewContext(
    '(async () => customFunction(payload))();',
    Object.freeze({ customFunction, payload }),
    { timeout: 3000 }
  );

  return result;
};
```

